const classifications=["Atendido","Parcialmente atendido","Não atendido","Não demonstrado","Não aplicável","Pendente de avaliação"];
function App(){
 const [session,setSession]=useState<any>(null),[loading,setLoading]=useState(true),[email,setEmail]=useState(""),[password,setPassword]=useState(""),[error,setError]=useState("");
 const [demo,setDemo]=useState(false),[active,setActive]=useState(()=>new URLSearchParams(window.location.search).has("checklist")?12:0),[mobile,setMobile]=useState(false),[query,setQuery]=useState(""),[sector,setSector]=useState("Todos os setores"),[risk,setRisk]=useState("Todos os riscos"),[selected,setSelected]=useState<DemoMachine|null>(null),[period,setPeriod]=useState("Últimos 30 dias");
 useEffect(()=>{if(!supabase){setLoading(false);return;}supabase.auth.getSession().then(({data})=>{setSession(data.session);setLoading(false)});const {data}=supabase.auth.onAuthStateChange((_e,s)=>setSession(s));return()=>data.subscription.unsubscribe()},[]);
 const [live,setLive]=useState<any[]>([]),[orgId,setOrgId]=useState<string|null>(null),[checklists,setChecklists]=useState<any[]>([]);
 useEffect(()=>{if(!session||!supabase||demo)return;let channel:any;let cancelled=false;(async()=>{const {data:membership}=await supabase!.from("organization_memberships").select("organization_id").eq("user_id",session.user.id).eq("status","active").limit(1).maybeSingle();if(cancelled)return;if(membership?.organization_id)setOrgId(membership.organization_id);const {data,error}=await supabase!.from("machines").select("id,tag,name,machine_type,manufacturer,model,status,adequacy_stage,unit_id,sector_id,sectors(name)").order("tag");if(cancelled)return;if(error)setError(error.message);else setLive((data??[]).map((m:any)=>({...m,type:m.machine_type,sector_name:m.sectors?.name??"Sem setor"})));if(membership?.organization_id){const {data:rows}=await supabase!.from("daily_checklists").select("*").eq("organization_id",membership.organization_id).order("created_at",{ascending:false});if(!cancelled)setChecklists(rows??[]);channel=supabase!.channel("daily-checklists-live").on("postgres_changes",{event:"*",schema:"public",table:"daily_checklists",filter:"organization_id=eq."+membership.organization_id},payload=>{setChecklists(prev=>{const row:any=payload.new??payload.old;if(payload.eventType==="DELETE")return prev.filter(x=>x.id!==row.id);return [row,...prev.filter(x=>x.id!==row.id)]})}).subscribe()}})();return()=>{cancelled=true;if(channel)supabase?.removeChannel(channel)}},[session,demo]);
 const machines=demo?demoMachines:live;
 const [demoChecks,setDemoChecks]=useState<any[]>(()=>demoMachines.flatMap((m,i)=>["1º turno","2º turno","3º turno"].map((shift,j)=>({id:m.id+"-"+j,machine_id:m.id,tag:m.tag,machine_name:m.name,sector:m.sector,shift,status:(i+j)%11===0?"sem_operacao":(i+j)%7===0?"nao_conforme":(i+j)%4===0?"pendente":"conforme",operator_name:people[(i+j)%people.length],supervisor_name:people[(i+j+2)%people.length],completed_at:(i+j)%4===0?null:new Date(Date.now()-((i+j)%8)*3600000).toISOString(),nonconformities:(i+j)%7===0?[{item:"Proteção móvel / intertravamento",description:"Falha identificada na inspeção"}]:[]}))));
 const filtered=useMemo(()=>machines.filter((m:any)=>(String(m.tag+" "+m.name+" "+(m.type??"")+" "+(m.sector??m.sector_name??"")).toLowerCase().includes(query.toLowerCase()))&&(sector==="Todos os setores"||(m.sector??m.sector_name)===sector)&&(risk==="Todos os riscos"||m.risk===risk)),[machines,query,sector,risk]);
 async function login(e:FormEvent){e.preventDefault();setError("");const {error}=await supabase!.auth.signInWithPassword({email,password});if(error)setError(error.message)}
 async function logout(){if(!demo)await supabase?.auth.signOut();setSession(null);setDemo(false);setSelected(null);setActive(0)}
 if(loading)return <div className="loading">Carregando CONECTASEG-NR12 CONTROL...</div>;
 if(!session)return <main className="login-wrap"><section className="login-card login-wide"><Brand/><span className="eyebrow">PLATAFORMA DE GESTÃO INDUSTRIAL</span><h1>Acesse sua plataforma</h1><p className="muted">Gestão integrada de máquinas, riscos, adequações e validações NR-12.</p><form className="form" onSubmit={login}><label>E-mail corporativo<input type="email" required value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Senha<input type="password" required value={password} onChange={e=>setPassword(e.target.value)}/></label>{error&&<div className="error">{error}</div>}<button className="primary full">Entrar no ambiente corporativo</button></form><div className="demo-divider"><span>OU EXPLORE ANTES DE ENTRAR</span></div><button className="demo-entry" onClick={()=>{setDemo(true);setSession({user:{email:"visitante.demo@conectaseg.local"}})}}><Factory/><span><b>Entrar no ambiente DEMONSTRATIVO</b><small>100 máquinas • 18 módulos • dados e documentos fictícios</small></span><ChevronRight/></button><small>Ambiente isolado. A demonstração não grava nem altera o banco corporativo.</small></section></main>;
 return <div className="app-shell"><aside className={"sidebar "+(mobile?"open":"")}><div className="brand-row"><Brand compact/><button className="icon-btn mobile-close" onClick={()=>setMobile(false)}><X/></button></div>{demo&&<div className="demo-side-label">AMBIENTE DEMONSTRATIVO • DADOS FICTÍCIOS</div>}<div className="nav-label">GESTÃO INTEGRADA NR-12</div><div className="nav-scroll">{modules.map(([label,Icon],i)=><button key={label} className={"nav-item "+(active===i&&!selected?"selected":"")} onClick={()=>{setActive(i);setSelected(null);setMobile(false);setQuery("")}}><Icon size={17}/><span>{label}</span></button>)}</div><div className="sidebar-bottom"><Factory size={17}/><span>{demo?"Planta Manaus • 100 máquinas":"Ambiente corporativo"}</span></div></aside>{mobile&&<div className="scrim" onClick={()=>setMobile(false)}/>}<main className="main-area"><header className="topbar"><button className="icon-btn mobile-menu" onClick={()=>setMobile(true)}><Menu/></button><div><span className="eyebrow">CONECTASEG-NR12 CONTROL</span><h2>{selected?selected.tag:modules[active][0]}</h2></div><div className="user-area">{demo&&<span className="demo-chip">DEMO</span>}<span>{session.user.email}</span><button className="icon-btn" title="Sair" onClick={logout}><LogOut size={17}/></button></div></header>{demo&&<div className="demo-banner"><AlertTriangle size={16}/><span><b>AMBIENTE FICTÍCIO:</b> empresa, pessoas, máquinas, fotos, riscos, resultados e documentos são sintéticos. Não representam avaliação técnica ou conformidade real.</span><button onClick={logout}>Sair da demonstração</button></div>}{selected?<MachineDetail machine={selected} onBack={()=>setSelected(null)}/>:active===0?<Dashboard demo={demo} machines={machines} period={period} setPeriod={setPeriod} onSelect={setSelected}/>:<ModulePage index={active} demo={demo} machines={filtered} checklists={demo?demoChecks:checklists} orgId={orgId} onSaveChecklist={(row:any)=>demo?setDemoChecks(prev=>[row,...prev.filter(x=>!(x.machine_id===row.machine_id&&x.shift===row.shift))]):setChecklists(prev=>[row,...prev.filter(x=>x.id!==row.id)])} query={query} setQuery={setQuery} sector={sector} setSector={setSector} risk={risk} setRisk={setRisk} onSelect={setSelected}/>}</main></div>
}
function Brand({compact=false}:{compact?:boolean}){return <div className="brand"><div className="brand-mark"><ShieldCheck size={compact?22:28}/></div><div><strong>CONECTASEG</strong><b>NR12 CONTROL</b>{!compact&&<small>Gestão integrada de máquinas e equipamentos</small>}</div></div>}
function Head({eyebrow,title,desc,children}:{eyebrow:string;title:string;desc:string;children?:ReactNode}){return <div className="page-head"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{desc}</p></div>{children}</div>}
function Panel({title,sub,children}:{title:string;sub?:string;children:ReactNode}){return <section className="panel"><div className="panel-head"><div><h3>{title}</h3>{sub&&<p>{sub}</p>}</div></div>{children}</section>}
function Risk({value}:{value:string}){return <span className={"risk-pill "+value.toLowerCase().replace("í","i").replaceAll(" ","-")}>{value}</span>}
function Dashboard({demo,machines,period,setPeriod,onSelect}:{demo:boolean;machines:any[];period:string;setPeriod:(v:string)=>void;onSelect:(m:DemoMachine)=>void}){
 const total=machines.length,critical=demo?machines.filter((m:DemoMachine)=>m.risk==="Crítico").length:0;
 const bars=[["Injeção",92],["Estamparia",88],["Usinagem",81],["Montagem",76],["SMT",72],["Utilidades",67],["Manutenção",58]];
 return <div className="content"><Head eyebrow="VISÃO EXECUTIVA DA PLANTA" title="Dashboard Gerencial da Planta" desc={demo?demoCompany.name+" • "+demoCompany.unit:"Indicadores consolidados da organização e unidades."}><select className="filter-select" value={period} onChange={e=>setPeriod(e.target.value)}><option>Últimos 30 dias</option><option>Últimos 90 dias</option><option>Ano atual</option></select></Head>{demo&&<div className="company-strip"><Building2/><div><b>{demoCompany.name}</b><span>{"CNPJ fictício "+demoCompany.cnpj+" • "+demoCompany.address}</span></div><span className="fiction-tag">BASE DEMO</span></div>}<div className="stats-grid">{[[total,"Máquinas e equipamentos",Wrench,"blue"],[demo?28:"—","Em adequação",Activity,"orange"],[demo?12:"—","Não conformes",AlertTriangle,"red"],[demo?10:"—","Sem diagnóstico",Eye,"gray"],[demo?critical:"—","Riscos críticos",AlertTriangle,"red"],[demo?36:"—","Ações em aberto",ClipboardCheck,"orange"],[demo?"86%":"—","Cobertura de checklist",ListChecks,"green"],[demo?"78%":"—","Itens conformes",CheckCircle2,"green"]].map(([v,l,I,c]:any)=><article className="stat-card" key={l}><div className={"stat-icon "+c}><I/></div><div><strong>{v}</strong><span>{l}</span></div></article>)}</div><div className="dashboard-grid"><Panel title="Conformidade NR-12 por setor" sub="Percentual demonstrativo por setor"><div className="hbar-chart">{bars.map(([n,v]:any)=><div key={n}><b>{n}</b><div className="bar-track"><i style={{width:v+"%"}}/></div><strong>{v}%</strong></div>)}</div></Panel><Panel title="Status das máquinas" sub="Situação cadastral demonstrativa"><div className="donut-wrap"><div className="donut"><span><b>{total}</b><small>Máquinas</small></span></div><div className="legend"><span><i className="green-dot"/>Avaliadas / conformes <b>60%</b></span><span><i className="amber-dot"/>Em adequação <b>28%</b></span><span><i className="red-dot"/>Não conformes <b>12%</b></span></div></div></Panel><Panel title="Distribuição de risco — HRN" sub="Faixas ilustrativas da metodologia demo"><div className="column-chart">{[["Baixo",12],["Moderado",28],["Alto",42],["Crítico",68]].map(([n,v]:any)=><div key={n}><b>{v}</b><i style={{height:v+"%"}}/><span>{n}</span></div>)}</div></Panel><Panel title="Distribuição por categoria" sub="Categoria não equivale a PL ou SIL"><div className="donut-wrap"><div className="donut category-donut"><span><b>100</b><small>Máquinas</small></span></div><div className="legend"><span>Cat. 4 <b>45%</b></span><span>Cat. 3 <b>25%</b></span><span>Cat. 2 <b>16%</b></span><span>Cat. 1 / pendente <b>14%</b></span></div></div></Panel><Panel title="Evolução mensal da conformidade" sub="Série histórica fictícia"><div className="line-chart"><svg viewBox="0 0 500 160" role="img" aria-label="Evolução fictícia"><polyline points="20,120 95,105 170,95 245,78 320,65 395,48 475,48" fill="none" stroke="#15965a" strokeWidth="4"/>{[[20,120],[95,105],[170,95],[245,78],[320,65],[395,48],[475,48]].map(([x,y],i)=><circle key={i} cx={x} cy={y} r="5" fill="#15965a"/>)}</svg><div className="axis-labels"><span>Jun</span><span>Jul</span><span>Ago</span><span>Set</span><span>Out</span><span>Nov</span><span>Dez</span></div></div></Panel><Panel title="Plano de ação — visão geral" sub="Distribuição por status"><div className="progress-list">{[["Em execução",18,50],["Pendente",10,28],["Concluída",8,22]].map(([n,v,p]:any)=><div key={n}><span>{n}</span><b>{v}</b><div className="bar-track"><i style={{width:p+"%"}}/></div></div>)}</div></Panel><Panel title="Máquinas prioritárias" sub="Clique para abrir a ficha completa"><div className="table-scroll"><table><thead><tr><th>TAG / Equipamento</th><th>Setor</th><th>Perigo principal</th><th>HRN demo</th><th>Nível</th><th/></tr></thead><tbody>{(demo?machines.filter((m:DemoMachine)=>m.risk==="Crítico"||m.risk==="Alto").slice(0,8):machines.slice(0,8)).map((m:any)=><tr key={m.id}><td><b>{m.tag} — {m.name}</b></td><td>{m.sector??m.sector_name}</td><td>{m.hazards?.[0]??"Não avaliado"}</td><td>{m.hrn??"—"}</td><td><Risk value={m.risk??"Não avaliado"}/></td><td><button className="text-btn" onClick={()=>demo&&onSelect(m)}>Abrir ficha</button></td></tr>)}</tbody></table></div></Panel></div><div className="note"><AlertTriangle size={17}/>{demo?"Todos os números são fictícios. HRN, categoria e percentuais não constituem avaliação normativa.":"Ausência de diagnóstico não equivale a conformidade."}</div></div>
}
function ModulePage({index,demo,machines,query,setQuery,sector,setSector,risk,setRisk,onSelect,checklists,orgId,onSaveChecklist}:{index:number;demo:boolean;machines:any[];query:string;setQuery:(v:string)=>void;sector:string;setSector:(v:string)=>void;risk:string;setRisk:(v:string)=>void;onSelect:(m:DemoMachine)=>void;checklists:any[];orgId:string|null;onSaveChecklist:(row:any)=>void}){
 const title=modules[index][0] as string,desc=modules[index][2] as string;const [tab,setTab]=useState("Visão geral"),[form,setForm]=useState(false);
 return <div className="content"><Head eyebrow={"MÓDULO "+String(index+1).padStart(2,"0")+" / 19"} title={title} desc={desc}><button className="secondary" onClick={()=>setForm(!form)}>＋ Novo registro</button></Head><div className="module-tabs">{(index===1?["Visão geral","Unidades","Setores e linhas","Usuários e permissões"]:index===2?["Visão geral","Importação","Documentos"]:["Visão geral","Registros","Evidências","Histórico"]).map(t=><button key={t} className={tab===t?"active":""} onClick={()=>setTab(t)}>{t}</button>)}</div>{form&&<Panel title="Formulário de novo registro" sub="Prévia interativa de homologação — não grava no banco"><div className="demo-form-grid"><label>Identificação<input placeholder="Ex.: REG-001"/></label><label>Máquina<select><option>Selecione uma máquina</option>{demoMachines.slice(0,20).map(m=><option key={m.id}>{m.tag} — {m.name}</option>)}</select></label><label>Responsável<input placeholder="Responsável fictício"/></label><label>Status<select><option>Pendente</option><option>Em análise</option><option>Concluído</option></select></label><label className="form-wide">Descrição<textarea placeholder="Descreva o registro, evidência ou observação..."/></label><button className="primary" onClick={()=>{setForm(false);alert("Simulação preenchida. Nenhum dado foi gravado.")}}>Simular cadastro</button></div></Panel>}
 {index===1?<Company/>:index===2?<Inventory machines={machines} query={query} setQuery={setQuery} sector={sector} setSector={setSector} risk={risk} setRisk={setRisk} onSelect={onSelect}/>:index===3?<Diagnostic/>:index===4?<CategoryModule/>:index===5?<RiskModule/>:index===6?<Devices/>:index===7?<Electrical/>:index===8?<Loto/>:index===9?<Actions/>:index===10?<Timeline/>:index===11?<Training/>:index===12?<Checklist demo={demo} machines={machines} checklists={checklists} orgId={orgId} onSave={onSaveChecklist}/>:index===13?<DailyChecks demo={demo} machines={machines} checklists={checklists}/>:index===14?<Tests/>:index===15?<Reports/>:index===16?<BI/>:index===17?<Standards/>:index===18?<Audit/>:<Panel title="Dashboard" sub="Indicadores do escopo"><p>Selecione um módulo para visualizar os registros.</p></Panel>}
 </div>
}
function Inventory({machines,query,setQuery,sector,setSector,risk,setRisk,onSelect}:{machines:any[];query:string;setQuery:(v:string)=>void;sector:string;setSector:(v:string)=>void;risk:string;setRisk:(v:string)=>void;onSelect:(m:DemoMachine)=>void}){return <><div className="filter-row"><div className="search-box"><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar TAG, nome, tipo, fabricante ou setor"/></div><select value={sector} onChange={e=>setSector(e.target.value)}><option>Todos os setores</option>{sectors.map(s=><option key={s}>{s}</option>)}</select><select value={risk} onChange={e=>setRisk(e.target.value)}><option>Todos os riscos</option>{["Crítico","Alto","Moderado","Baixo"].map(s=><option key={s}>{s}</option>)}</select><span className="tag">{machines.length} registros</span></div><div className="machine-grid">{machines.map((m:any)=><button className="machine-card" key={m.id} onClick={()=>onSelect(m)}><img src={m.image} alt={m.type??m.name}/><div className="machine-card-body"><div className="machine-card-top"><b>{m.tag}</b><Risk value={m.risk??"Não avaliado"}/></div><h3>{m.name}</h3><p>{m.type} • {m.sector}</p><div className="machine-meta"><span>{m.manufacturer??"—"} • {m.model??"—"}</span><span>HRN {m.hrn??"—"}</span></div><div className="machine-open">Ficha completa <ChevronRight size={14}/></div></div></button>)}</div></>}
function Company(){return <><div className="org-tree"><div><b>Organização</b><span>{demoCompany.name}</span></div><i/><div><b>Unidade / Planta</b><span>{demoCompany.unit}</span></div><i/><div><b>Setores e linhas</b><span>10 setores • 6 linhas • 100 equipamentos</span></div></div><div className="table-scroll"><table><thead><tr><th>Código</th><th>Setor</th><th>Linhas</th><th>Máquinas</th><th>Responsável fictício</th><th>Status</th></tr></thead><tbody>{sectors.map((s,i)=><tr key={s}><td>SET-{String(i+1).padStart(2,"0")}</td><td>{s}</td><td>{i%3+1}</td><td>10</td><td>{people[i%8]}</td><td>Ativo — DEMO</td></tr>)}</tbody></table></div></>}
function Diagnostic(){const items=["Identificação e documentação da máquina","Apreciação de riscos e medidas de redução","Proteções fixas e móveis","Dispositivos de intertravamento","Sistemas de comando relacionados à segurança","Parada de emergência","Prevenção de partida inesperada","Instalações e painéis elétricos","Aterramento e equipotencialização","Sistemas hidráulicos e pneumáticos","LOTO e energia zero","Sinalização, manuais e procedimentos","Ergonomia e aspectos ambientais","Capacitação e autorização","Testes, validação e parecer técnico"];return <><div className="module-summary-grid">{[["Sessões",100],["Requisitos de referência",15],["Não demonstrados",42]].map(([a,b])=><div className="module-stat" key={a}><b>{b}</b><span>{a}</span></div>)}</div><div className="table-scroll"><table><thead><tr><th>Seção / requisito</th><th>Aplicabilidade</th><th>Classificação demo</th><th>Evidência esperada</th><th>Referência</th></tr></thead><tbody>{items.map((x,i)=><tr key={x}><td><b>{String(i+1).padStart(2,"0")} — {x}</b></td><td>{i===9?"Quando aplicável":"Confirmar escopo"}</td><td><Risk value={classifications[i%6]}/></td><td>{["Foto geral e placa","Documento, folha ou registro","Foto, medição e inspeção"][i%3]}</td><td>Item e edição a conferir</td></tr>)}</tbody></table></div><div className="note">Estrutura demonstrativa, não transcrição integral da NR-12. Associar item e edição somente após conferência oficial.</div></>}
function RiskModule(){return <><div className="formula-box"><b>HRN = LO × FE × DPH × NP</b><span>Guardar descrição dos fatores, escala, memória de cálculo, autor, data, risco inicial e residual.</span></div><div className="table-scroll"><table><thead><tr><th>Perigo / tarefa</th><th>Zona / fonte</th><th>LO</th><th>FE</th><th>DPH</th><th>NP</th><th>HRN inicial</th><th>Residual</th><th>Nível</th></tr></thead><tbody>{demoRisks.concat(demoRisks).map((r,i)=><tr key={r.hazard+i}><td><b>{r.hazard}</b><small>Operação / limpeza / manutenção</small></td><td>{r.source}</td><td>{[3,4,5][i%3]}</td><td>{[4,5,6][i%3]}</td><td>{[8,10,12][i%3]}</td><td>{[2,3,4][i%3]}</td><td>{[192,480,720,240,360,576][i%6]}</td><td>{[48,120,144,60,90,96][i%6]}</td><td><Risk value={r.severity}/></td></tr>)}</tbody></table></div><Panel title="Parâmetros da metodologia" sub="Escalas ilustrativas, configuráveis por organização"><div className="parameter-grid">{[["LO","Probabilidade de ocorrência"],["FE","Frequência / tempo de exposição"],["DPH","Grau de possível dano"],["NP","Número de pessoas expostas"]].map(([a,b])=><div key={a}><b>{a}</b><span>{b}</span><small>Escala demo • confirmar metodologia</small></div>)}</div></Panel></>}
function Devices(){return <><Panel title="Catálogo de dispositivos" sub="Componentes associados à máquina e função"><div className="device-catalog">{demoDeviceTypes.concat([{name:"Chave magnética codificada",purpose:"Intertravamento de proteção",standard:"ISO 14119"},{name:"Comando bimanual",purpose:"Comando de atuação segura",standard:"ISO 13851"},{name:"Contator com EDM",purpose:"Monitoramento de contatores",standard:"ISO 13849-1"},{name:"Seccionadora bloqueável",purpose:"Isolamento para LOTO",standard:"IEC 60204-1"}]).map(d=><article key={d.name}><div className="device-icon"><ShieldCheck/></div><div><h3>{d.name}</h3><p>{d.purpose}</p><small>{d.standard} • DEMO</small></div></article>)}</div></Panel><Panel title="Funções de segurança — análise por função" sub="Categoria, PLr, PL alcançado e SIL são campos independentes"><div className="table-scroll"><table><thead><tr><th>Função</th><th>Perigo controlado</th><th>Categoria requerida</th><th>PLr</th><th>PL alcançado</th><th>SIL</th><th>Validação</th></tr></thead><tbody>{["SF-01 Parada por abertura de proteção","SF-02 Parada de emergência","SF-03 Prevenção de partida inesperada","SF-04 Corte pneumático seguro"].map((x,i)=><tr key={x}><td><b>{x}</b></td><td>{["Zona de prensagem","Emergência operacional","Intervenção e manutenção","Energia pneumática residual"][i]}</td><td>A definir</td><td>{["PLr d","PLr c","PLr d","A avaliar"][i]}</td><td>Não demonstrado</td><td>Não avaliado</td><td><Risk value="Pendente de avaliação"/></td></tr>)}</tbody></table></div></Panel><div className="note">Não converter Categoria ↔ PL ↔ SIL. Categoria 4 exige comprovação de arquitetura, comportamento em falhas, diagnóstico e validação.</div></>}
function Electrical(){return <><Panel title="Documentos elétricos e diagramas" sub="Revisões, folhas, bornes e evidências"><div className="table-scroll"><table><thead><tr><th>Documento</th><th>Máquina</th><th>Revisão</th><th>Folhas</th><th>Verificação</th><th>Arquivo</th></tr></thead><tbody>{["Diagrama de força","Diagrama de comando","Circuito de segurança","Relatório de aterramento","Lista de componentes"].map((x,i)=><tr key={x}><td>{x}</td><td>{demoMachines[i].tag}</td><td>Rev. 02 — demo</td><td>{i+2}</td><td><Risk value={i===3?"Não demonstrado":"Pendente de avaliação"}/></td><td>Prévia fictícia</td></tr>)}</tbody></table></div></Panel><Panel title="Arquitetura de referência da função"><div className="flow-diagram">{["Sensor / entrada","Relé / lógica","Contator / saída","Estado seguro"].map((x,i)=><div key={x}><span>0{i+1}</span><b>{x}</b>{i<3&&<ChevronRight/>}</div>)}</div><div className="note">Fotografia não comprova continuidade, ligação interna ou aterramento. Sem medição/documento: Não demonstrado.</div></Panel></>}
function Loto(){const src=["Elétrica","Pneumática","Hidráulica","Mecânica","Gravitacional","Térmica","Química","Pressão acumulada"];return <><Panel title="Matriz de fontes de energia" sub="Pontos de isolamento, energia residual e verificação"><div className="table-scroll"><table><thead><tr><th>Fonte</th><th>Ponto de isolamento</th><th>Bloqueio</th><th>Energia residual</th><th>Verificação zero</th><th>Status</th></tr></thead><tbody>{src.map((s,i)=><tr key={s}><td><b>{s}</b></td><td>{["QDG / seccionadora","Válvula geral","Bloco hidráulico","Bloqueio mecânico"][i%4]}</td><td>{["Cadeado + etiqueta","Bloqueio de válvula","Trava mecânica"][i%3]}</td><td>{i%2?"Pressão / movimento":"Tensão / inércia"}</td><td>Método e responsável pendentes</td><td><Risk value="Pendente de avaliação"/></td></tr>)}</tbody></table></div></Panel><Panel title="Sequência do procedimento LOTO"><div className="step-grid">{["Preparar e comunicar","Parar equipamento","Isolar todas as fontes","Aplicar bloqueio individual","Dissipar energia acumulada","Verificar energia zero","Executar serviço","Retirar bloqueios e retornar"].map((s,i)=><div key={s}><b>{i+1}</b><span>{s}</span></div>)}</div><div className="note">Parada de emergência não substitui seccionamento, bloqueio e verificação de energia zero.</div></Panel></>}
function Actions(){const stages=["Planejada","Aprovada","Em execução","Aguardando material","Aguardando validação","Concluída","Vencida"];return <><div className="module-summary-grid">{[["Ações abertas",36],["Vencidas",7],["Aguardando validação",5],["Custo estimado","R$ 284 mil"]].map(([a,b])=><div className="module-stat" key={a}><b>{b}</b><span>{a}</span></div>)}</div><div className="action-board">{stages.slice(0,4).map((s,i)=><div key={s}><h4>{s}</h4>{demoMachines.slice(i*3,i*3+3).map((m,j)=><article key={m.id}><b>{m.tag} — {m.name}</b><span>{m.actions[j%m.actions.length]}</span><small>{people[(i+j)%8]} • Prazo {String(15+j).padStart(2,"0")}/12/2026</small><Risk value={i===2?"Crítico":"Alto"}/></article>)}</div>)}</div><Panel title="Ações e evidências" sub="Conclusão exige evidência e validação técnica"><div className="table-scroll"><table><thead><tr><th>ID</th><th>Origem / GAP</th><th>Criticidade</th><th>Responsável</th><th>Prazo</th><th>Custo estimado</th><th>Status</th></tr></thead><tbody>{demoMachines.slice(0,10).map((m,i)=><tr key={m.id}><td>ACT-{String(i+1).padStart(3,"0")}</td><td>{m.tag} — {m.actions[0]}</td><td>C{i%4+1}</td><td>{people[i%8]}</td><td>{String(15+i).padStart(2,"0")}/12/2026</td><td>R$ {(4500+i*1250).toLocaleString("pt-BR")}</td><td>{stages[i%7]}</td></tr>)}</tbody></table></div></Panel></>}
function Training(){return <><Panel title="Matriz de capacitação e autorização" sub="Treinamento não gera autorização automática"><div className="table-scroll"><table><thead><tr><th>Trabalhador</th><th>Matrícula</th><th>Função</th><th>Treinamento</th><th>Data</th><th>Validade demo</th><th>Máquina autorizada</th></tr></thead><tbody>{people.map((p,i)=><tr key={p}><td><b>{p}</b></td><td>COL-{120+i}</td><td>{["Operador SMT","Operador de injetora","Mecânico","Eletricista"][i%4]}</td><td>{["NR-12 básico","Segurança em injetoras","LOTO","Segurança elétrica"][i%4]}</td><td>10/05/2026</td><td>{i%3?"Válido até 10/05/2027":"A revisar"}</td><td>{demoMachines[i].tag}</td></tr>)}</tbody></table></div></Panel><Panel title="Documentos de treinamento"><FileList names={["Conteúdo programático NR-12","Lista de presença","Avaliação de aprendizagem","Certificados individuais","Matriz de autorização por máquina"]}/></Panel></>}
function Checklist({demo,machines,checklists,orgId,onSave}:{demo:boolean;machines:any[];checklists:any[];orgId:string|null;onSave:(row:any)=>void}){
 const items=["Proteções fixas","Proteções móveis e intertravamentos","Cortina de luz / scanner","Parada de emergência","Comandos e sinalização","Vazamentos pneumáticos/hidráulicos","Organização da área","Ausência de bypass"];
 const params=new URLSearchParams(window.location.search),requested=params.get("checklist");
 const [machineId,setMachineId]=useState(String(machines.find((m:any)=>m.tag===requested||m.id===requested)?.id??machines[0]?.id??""));
 const [shift,setShift]=useState("1º turno"),[operator,setOperator]=useState(""),[supervisor,setSupervisor]=useState(""),[operation,setOperation]=useState("operando"),[answers,setAnswers]=useState<Record<string,string>>({}),[notes,setNotes]=useState<Record<string,string>>({}),[saving,setSaving]=useState(false),[message,setMessage]=useState("");
 useEffect(()=>{if(!machineId&&machines.length){const target=machines.find((m:any)=>m.tag===requested||m.id===requested)??machines[0];setMachineId(String(target.id))}},[machines,machineId,requested]);
 const machine=machines.find((m:any)=>String(m.id)===machineId),link=machine?window.location.origin+"/?checklist="+encodeURIComponent(machine.tag):"";
 async function submit(){if(!machine||!supervisor.trim()||(operation==="operando"&&(!operator.trim()||items.some(x=>!answers[x])))){setMessage("Selecione a máquina, informe o supervisor e complete os campos obrigatórios do operador.");return}
 const nc=operation==="sem_operacao"?[]:items.filter(x=>answers[x]==="Não conforme"||answers[x]==="Não verificado").map(x=>({item:x,description:notes[x]||(answers[x]==="Não verificado"?"Item não verificado":"Não conformidade identificada")}));
 const row:any={machine_id:machine.id,tag:machine.tag,machine_name:machine.name,sector:machine.sector??machine.sector_name??"",shift,status:operation==="sem_operacao"?"sem_operacao":nc.length?"nao_conforme":"conforme",operator_name:operator,supervisor_name:supervisor,completed_at:new Date().toISOString(),check_date:new Date().toLocaleDateString("en-CA"),answers:operation==="sem_operacao"?[]:items.map(item=>({item,status:answers[item],observation:notes[item]??""})),nonconformities:nc};
 if(!demo){if(!supabase||!orgId){setMessage("Usuário sem organização vinculada.");return}setSaving(true);const user=await supabase.auth.getUser();const {data,error}=await supabase.from("daily_checklists").upsert({...row,organization_id:orgId,unit_id:machine.unit_id??null,sector_id:machine.sector_id??null,created_by:user.data.user?.id??null,check_date:new Date().toISOString().slice(0,10)},{onConflict:"machine_id,check_date,shift"}).select().single();setSaving(false);if(error){setMessage("Erro ao salvar: "+error.message);return}onSave(data)}else onSave(row);
 setMessage(nc.length?"Checklist salvo com "+nc.length+" não conformidade(s). Supervisor sinalizado.":"Checklist salvo como CONFORME.");setAnswers({});setNotes({});
 }
 return <div className="checklist-page"><Panel title="Identificação da inspeção" sub="Acesso por QR Code direciona para a máquina específica"><div className="demo-form-grid"><label>Máquina / TAG<select value={machineId} onChange={e=>setMachineId(e.target.value)}>{machines.map((m:any)=><option key={m.id} value={m.id}>{m.tag} — {m.name}</option>)}</select></label><label>Turno<select value={shift} onChange={e=>setShift(e.target.value)}><option>1º turno</option><option>2º turno</option><option>3º turno</option></select></label><label>Operador responsável<input value={operator} onChange={e=>setOperator(e.target.value)} placeholder="Nome / matrícula"/></label><label>Supervisor do turno<input value={supervisor} onChange={e=>setSupervisor(e.target.value)} placeholder="Nome do supervisor"/></label><label>Condição da máquina<select value={operation} onChange={e=>setOperation(e.target.value)}><option value="operando">Em operação — inspecionar</option><option value="sem_operacao">Sem operação neste turno</option></select></label></div>{machine&&<div className="qr-access"><img src={"https://api.qrserver.com/v1/create-qr-code/?size=150x150&data="+encodeURIComponent(link)} alt={"QR "+machine.tag}/><div><b>QR Code individual — {machine.tag}</b><span>Link direto para o checklist desta máquina</span><code>{link}</code><button className="secondary" onClick={()=>navigator.clipboard?.writeText(link)}><Copy size={14}/> Copiar link</button></div></div>}</Panel><Panel title="Checklist pré-operacional" sub="Classifique cada item e registre observações nas não conformidades">{operation==="sem_operacao"?<div className="note">A máquina será registrada em amarelo como SEM OPERAÇÃO. O supervisor deve confirmar esta condição.</div>:<div className="checklist-items">{items.map((x,i)=><div key={x} className={answers[x]==="Não conforme"?"check-nc":""}><b>{String(i+1).padStart(2,"0")}. {x}</b><select value={answers[x]??""} onChange={e=>setAnswers({...answers,[x]:e.target.value})}><option value="">Selecione</option><option>Conforme</option><option>Não conforme</option><option>Não aplicável</option><option>Não verificado</option></select><input value={notes[x]??""} onChange={e=>setNotes({...notes,[x]:e.target.value})} placeholder="Observação / evidência"/></div>)}</div>}<button className="primary" disabled={saving} onClick={submit}>{saving?"Salvando...":operation==="sem_operacao"?"Registrar sem operação":"Finalizar e registrar checklist"}</button>{message&&<div className="note">{message}</div>}</Panel></div>
}
function DailyChecks({demo,machines,checklists}:{demo:boolean;machines:any[];checklists:any[]}){
 const [date,setDate]=useState(new Date().toISOString().slice(0,10)),[filterSector,setFilterSector]=useState("Todos"),[filterShift,setFilterShift]=useState("Todos"),shifts=["1º turno","2º turno","3º turno"];
 const rows=machines.filter((m:any)=>filterSector==="Todos"||(m.sector??m.sector_name)===filterSector);
 const get=(m:any,sh:string)=>checklists.find(c=>c.machine_id===m.id&&c.shift===sh&&String(c.check_date??c.completed_at??"").slice(0,10)===date);
 const visibleShifts=shifts.filter(sh=>filterShift==="Todos"||filterShift===sh);const status=(m:any,sh:string)=>get(m,sh)?.status??"nao_realizado",done=rows.reduce((n:number,m:any)=>n+visibleShifts.filter(sh=>["conforme","nao_conforme"].includes(status(m,sh))).length,0),idle=rows.reduce((n:number,m:any)=>n+visibleShifts.filter(sh=>status(m,sh)==="sem_operacao").length,0),missed=rows.reduce((n:number,m:any)=>n+visibleShifts.filter(sh=>status(m,sh)==="nao_realizado").length,0);
 const nc=rows.flatMap((m:any)=>visibleShifts.map(sh=>({m,sh,c:get(m,sh)})).filter(x=>x.c?.status==="nao_conforme")),total=rows.length*visibleShifts.length;
 const label=(st:string)=>st==="conforme"?"Realizado — conforme":st==="nao_conforme"?"NÃO CONFORME":st==="sem_operacao"?"Sem operação":"Não realizado";
 const dot=(st:string)=>st==="conforme"?"green":st==="sem_operacao"?"yellow":"red";
 const link=(m:any)=>"/?checklist="+encodeURIComponent(m.tag);
 return <div className="daily-dashboard"><Head eyebrow="MONITORAMENTO OPERACIONAL • TEMPO REAL" title="Dashboard de Checklists Diários" desc={demo?"Dados fictícios editáveis nesta sessão.":"Registros sincronizados pelo Supabase Realtime."}><span className="live-chip"><span className="live-dot"/>{demo?"DEMO LOCAL":"ATUALIZAÇÃO EM TEMPO REAL"}</span></Head><div className="daily-filters"><label>Data<input type="date" value={date} onChange={e=>setDate(e.target.value)}/></label><label>Setor<select value={filterSector} onChange={e=>setFilterSector(e.target.value)}><option>Todos</option>{sectors.map(x=><option key={x}>{x}</option>)}</select></label><label>Turno<select value={filterShift} onChange={e=>setFilterShift(e.target.value)}><option>Todos</option>{shifts.map(x=><option key={x}>{x}</option>)}</select></label></div><div className="daily-kpis">{[[total,"Checklists previstos"],[done,"Realizados"],[missed,"Não realizados"],[nc.length,"Não conformidades"],[idle,"Sem operação"]].map(([v,l]:any,i)=><div className="daily-kpi" key={l}><b>{v}</b><span>{l}</span><i className={["blue","green","red","orange"][i]}/></div>)}</div><Panel title="Quadro de realização por máquina e turno" sub="Verde = conforme • Vermelho = não realizado / não conforme • Amarelo = sem operação"><div className="table-scroll"><table className="shift-matrix"><thead><tr><th>TAG / Equipamento</th><th>Setor</th>{visibleShifts.map(x=><th key={x}>{x}</th>)}<th>QR / Link</th></tr></thead><tbody>{rows.map((m:any)=><tr key={m.id}><td><b>{m.tag} — {m.name}</b></td><td>{m.sector??m.sector_name??"—"}</td>{visibleShifts.map(sh=>{const c=get(m,sh),st=status(m,sh);return <td key={sh}><div className="shift-cell"><span className={"status-light "+dot(st)}/><span>{label(st)}</span>{c?.operator_name&&<small>Operador: {c.operator_name}</small>}{c?.supervisor_name&&<small>Supervisor: {c.supervisor_name}</small>}{c?.status==="nao_conforme"&&<strong className="alert-text">{(c.nonconformities??[]).length} NC(s)</strong>}</div></td>})}<td><a className="qr-link" href={link(m)} target="_blank" rel="noreferrer"><QrCode size={15}/> Abrir</a><button className="text-btn" onClick={()=>navigator.clipboard?.writeText(window.location.origin+link(m))}>Copiar link</button></td></tr>)}</tbody></table></div></Panel><div className="daily-bottom-grid"><Panel title="Não conformidades registradas" sub="Máquinas que exigem ação do supervisor"><div className="exception-list">{nc.length?nc.map(({m,sh,c}:any)=><article key={m.id+sh}><AlertTriangle/><div><b>{m.tag} — {m.name}</b><span>{sh} • Operador: {c.operator_name||"Não informado"}</span><small>Supervisor: {c.supervisor_name||"Não informado"}</small>{(c.nonconformities??[]).map((n:any,i:number)=><small key={i}>{n.item}: {n.description}</small>)}</div><Risk value="Não conforme"/></article>):<p className="muted">Nenhuma não conformidade para a data selecionada.</p>}</div></Panel><Panel title="Ausência de checklist" sub="Turnos sem registro exigem acompanhamento"><div className="exception-list">{rows.flatMap((m:any)=>shifts.map(sh=>({m,sh}))).filter(({m,sh}:any)=>status(m,sh)==="nao_realizado").slice(0,30).map(({m,sh}:any)=><article key={m.id+sh}><AlertTriangle/><div><b>{m.tag} — {m.name}</b><span>{sh} • Checklist não realizado</span><small>Operador não identificado • Supervisor deve apurar</small></div><Risk value="Não realizado"/></article>)}</div></Panel></div><div className="note">Amarelo “Sem operação” deve ser registrado pelo supervisor. Ausência de registro permanece vermelha e nunca é considerada conformidade.</div></div>
}
function CategoryModule(){return <div className="category-module"><Head eyebrow="FUNÇÕES DE SEGURANÇA" title="Categoria, Performance Level e SIL" desc="Comparação visual antes e depois da adequação. Representação conceitual, não laudo técnico."/><div className="category-comparison"><Panel title="ANTES DA ADEQUAÇÃO" sub="Condição inicial ilustrativa"><div className="machine-schematic before"><div className="machine-guard open-guard"><span>Zona perigosa acessível</span></div><div className="safety-flow"><div className="flow-node bad">Sensor / proteção<br/>não monitorada</div><ChevronRight/><div className="flow-node bad">Comando padrão<br/>sem diagnóstico</div><ChevronRight/><div className="flow-node bad">Atuação sem<br/>redundância provada</div></div><div className="category-result"><b>Categoria: não demonstrada</b><span>PL alcançado: não demonstrado</span><span>SIL: não avaliado</span></div></div></Panel><Panel title="DEPOIS DA ADEQUAÇÃO" sub="Arquitetura alvo ilustrativa — validar projeto"><div className="machine-schematic after"><div className="machine-guard closed-guard"><span>Proteção monitorada / acesso controlado</span></div><div className="safety-flow"><div className="flow-node good">Sensor codificado<br/>monitorado</div><ChevronRight/><div className="flow-node good">Relé / CLP de segurança<br/>diagnóstico</div><ChevronRight/><div className="flow-node good">Elementos finais<br/>monitorados</div></div><div className="category-result"><b>Categoria / PLr / PL: determinar por função</b><span>SIL: avaliar somente quando aplicável</span><span>Validação: cálculo e ensaios documentados</span></div></div></Panel></div><Panel title="Comparação técnica por função de segurança" sub="Categoria, PLr, PL alcançado e SIL são parâmetros distintos"><div className="table-scroll"><table><thead><tr><th>Elemento</th><th>Antes</th><th>Depois — alvo de projeto</th><th>Evidência necessária</th></tr></thead><tbody>{[["Arquitetura","Não demonstrada","Definida por função","Diagrama e especificação"],["Categoria","Não determinada","Requerida e alcançada verificadas","Análise de arquitetura e falhas"],["PLr / PL","Não calculado","PLr calculado; PL alcançado demonstrado","Dados de componentes e cálculo"],["SIL","Não avaliado","Avaliar somente se aplicável","Análise conforme norma aplicável"],["Diagnóstico","Sem evidência suficiente","Cobertura e falhas perigosas avaliadas","Dados de fabricante e validação"],["Validação","Pendente","Testes funcionais e de falha aprovados","Protocolo, resultados e responsável"]].map(r=><tr key={r[0]}>{r.map(x=><td key={x}>{x}</td>)}</tr>)}</tbody></table></div></Panel><div className="note"><AlertTriangle/>Esquemas ilustrativos, não desenhos de engenharia nem prova de Categoria, PL ou SIL. Não declarar Cat. 4, PL e ou SIL 3 sem especificação, cálculo e validação.</div></div>}
function Tests(){return <Panel title="Plano de testes das funções de segurança" sub="Procedimento, critério, executor, resultado e evidência"><div className="table-scroll"><table><thead><tr><th>Teste</th><th>Função</th><th>Procedimento / critério</th><th>Resultado</th><th>Executor</th><th>Evidência</th></tr></thead><tbody>{["Abertura de proteção durante ciclo","Acionamento da parada de emergência","Detecção de falha de contato","Reset após interrupção","Descarga pneumática"].map((x,i)=><tr key={x}><td><b>TST-{String(i+1).padStart(3,"0")}</b><small>{x}</small></td><td>SF-0{i+1}</td><td>Executar procedimento aprovado e registrar resposta esperada</td><td><Risk value={["Inconclusivo","Pendente de avaliação","Reprovado"][i%3]}/></td><td>{people[i]}</td><td>Foto / vídeo / relatório DEMO</td></tr>)}</tbody></table></div></Panel>}
function Reports(){return <><FileList names={["Laudo individual da máquina — INJ-003","Relatório consolidado da unidade Manaus","Matriz de apreciação de riscos","Relatório de funções de segurança","Plano de adequação por setor","Relatório de inspeções e checklists","Registro fotográfico por equipamento"]}/><div className="note">Minutas exigem revisão e aprovação de profissional competente. Não gerar ART, assinatura ou conclusão ausente.</div></>}
function FileList({names}:{names:string[]}){return <div className="file-list">{names.map((x,i)=><div key={x}><FileText/><b>{x}</b><span>Rev. 0{i+1} • Documento fictício / prévia</span><button className="secondary" onClick={()=>alert("Prévia demonstrativa sem valor de laudo.")}>Visualizar</button></div>)}</div>}
function BI(){return <><Panel title="Indicadores gerenciais" sub="Fórmulas e população demonstrativas"><div className="hbar-chart">{[["Cobertura do diagnóstico",88],["Cobertura de checklist",86],["Treinamentos válidos",92],["Ações concluídas",22],["Funções validadas",35]].map(([n,v]:any)=><div key={n}><b>{n}</b><div className="bar-track"><i style={{width:v+"%"}}/></div><strong>{v}%</strong></div>)}</div></Panel><Panel title="Relatórios disponíveis"><div className="report-grid">{["Inventário","Diagnóstico NR-12","APR / HRN","Categoria / PL / SIL","Dispositivos","Elétrica / aterramento","LOTO","Plano de ação","Checklists","Treinamentos","Testes","Auditoria"].map(x=><button key={x} onClick={()=>alert("Prévia fictícia: "+x)}><BarChart3/><b>{x}</b><Download size={15}/></button>)}</div></Panel></>}
function Standards(){const norms=["NR-01 — GRO/PGR","NR-10 — Segurança em eletricidade","NR-12 — Máquinas e equipamentos","NR-13 — Sistemas pressurizados (quando aplicável)","NR-15 — Agentes e atividades insalubres","NR-17 — Ergonomia","ABNT NBR ISO 12100 — Apreciação e redução de riscos","ABNT NBR 14153 — Categorias de segurança","ABNT NBR ISO 13849-1 — PL e arquitetura","ABNT NBR ISO 13849-2 — Validação","ISO 14119 — Intertravamentos","ISO 14120 — Proteções","ISO 13850 — Parada de emergência","ISO 13855 — Posicionamento de proteções","ISO 13857 — Distâncias de segurança","IEC 60204-1 — Equipamento elétrico de máquinas","ISO 4413 / ISO 4414 — Hidráulica e pneumática"];return <><div className="standards-grid">{norms.map((n,i)=><article key={n}><FileText/><b>{n}</b><span>{["GRO, inventário e plano de ação","Elétrica, LOTO e capacitação","Diagnóstico e proteções","Apreciação de riscos"][i%4]}</span><Risk value="Edição a verificar"/></article>)}</div><div className="note">Confirmar edição vigente, aplicabilidade e item exato em fonte oficial/autorizada antes de configurar critérios ou emitir parecer.</div></>}
function Audit(){return <><div className="module-summary-grid">{[["Usuários demo",8],["Eventos de auditoria",248],["Alertas ativos",12],["Perfis",6]].map(([a,b])=><div className="module-stat" key={a}><b>{b}</b><span>{a}</span></div>)}</div><div className="table-scroll"><table><thead><tr><th>Data/hora</th><th>Usuário fictício</th><th>Módulo</th><th>Evento</th><th>Entidade</th><th>Resultado</th></tr></thead><tbody>{["Atualização de cadastro","Upload de fotografia","Revisão de APR","Abertura de ação","Checklist enviado","Teste reprovado","Acesso ao laudo","Alteração de parâmetro"].map((x,i)=><tr key={x}><td>11/11/2026 0{i+8}:20</td><td>{people[i]}</td><td>{modules[(i+2)%18][0]}</td><td>{x}</td><td>{demoMachines[i].tag}</td><td>Registrado — DEMO</td></tr>)}</tbody></table></div></>}
function MachineDetail({machine:m,onBack}:{machine:DemoMachine;onBack:()=>void}){const [tab,setTab]=useState("Resumo");const tabs=["Resumo","Dados técnicos","Diagnóstico","Categoria / PL / SIL","APR / HRN","Funções de segurança","Dispositivos","Elétrica","LOTO","Plano de ação","Checklists","Treinamentos","Testes","Documentos","Timeline"];return <div className="content"><button className="back-link" onClick={onBack}><ArrowLeft size={16}/> Voltar ao inventário</button><div className="detail-hero"><img src={m.image} alt={m.type}/><div><span className="eyebrow">FICHA COMPLETA DO EQUIPAMENTO • {m.tag}</span><h1>{m.name}</h1><p>{m.description}</p><div className="detail-tags"><span>{m.type}</span><span>{m.sector} • {m.line}</span><Risk value={m.risk}/></div></div></div><div className="machine-tabs">{tabs.map(t=><button key={t} className={tab===t?"active":""} onClick={()=>setTab(t)}>{t}</button>)}</div>{tab==="Resumo"?<div className="detail-grid"><Panel title="Informações do equipamento"><Info items={[["TAG",m.tag],["Fabricante",m.manufacturer],["Modelo",m.model],["Nº de série",m.serial],["Ano",String(m.year)],["Potência",m.power],["Tensão",m.voltage],["Localização",m.sector+" • "+m.line],["Status operacional",m.status],["Criticidade",m.risk]]}/></Panel><Panel title="Categorias de risco"><div className="risk-cards">{["Mecânico","Elétrico","Ergonômico","Ruído","Térmico","Pneumático"].map((x,i)=><div key={x}><b>{x}</b><Risk value={i<2?"Alto":i===3?"Moderado":"Não demonstrado"}/><small>Perigo / condição a verificar</small></div>)}</div></Panel><Panel title="Performance e indicadores"><div className="mini-kpis">{[["Disponibilidade","92,4%"],["Checklists realizados","86%"],["Conformidade dos itens","78%"],["Tempo de parada","14,3 h"]].map(([a,b])=><div key={a}><span>{a}</span><b>{b}</b></div>)}</div></Panel><Panel title="HRN simulado"><div className="hrn-score"><strong>{m.hrn}</strong><span>HRN ilustrativo • risco {m.risk}</span></div><p>HRN = LO × FE × DPH × NP. Memória de cálculo ilustrativa; escalas devem ser configuradas.</p></Panel><Panel title="Dispositivos associados"><ul className="detail-list">{m.safeguards.map(x=><li key={x}>{x}</li>)}</ul></Panel><Panel title="Perigos e ações"><ul className="detail-list">{m.hazards.concat(m.actions).map(x=><li key={x}>{x}</li>)}</ul></Panel></div>:<Panel title={tab} sub={"Registros demonstrativos relacionados à máquina "+m.tag}><DetailTab tab={tab} machine={m}/></Panel>}<div className="note"><AlertTriangle size={17}/> Dados fictícios. Categoria, PLr, PL alcançado e SIL são avaliações independentes. Não há validação ou liberação automática.</div></div>}
function DetailTab({tab,machine:m}:{tab:string;machine:DemoMachine}){if(tab==="Categoria / PL / SIL")return <CategoryModule/>;if(tab==="Dados técnicos")return <Info items={[["Capacidade","320 t — exemplo"],["Energia principal","Elétrica e pneumática"],["Frequência","60 Hz"],["Área ocupada","18 m² — demo"],["Peso","12.500 kg — demo"],["Manual","Não demonstrado"],["ART","Não anexada"]]}/>;if(tab==="Diagnóstico")return <Diagnostic/>;if(tab==="Categoria / PL / SIL")return <CategoryModule/>;if(tab==="APR / HRN")return <RiskModule/>;if(tab==="Funções de segurança"||tab==="Dispositivos")return <Devices/>;if(tab==="Elétrica")return <Electrical/>;if(tab==="LOTO")return <Loto/>;if(tab==="Plano de ação")return <Actions/>;if(tab==="Checklists")return <Checklist/>;if(tab==="Treinamentos")return <Training/>;if(tab==="Testes")return <Tests/>;if(tab==="Timeline")return <Timeline/>;return <Reports/>}
function Info({items}:{items:string[][]}){return <div className="info-grid">{items.map(([a,b])=><div key={a}><small>{a}</small><b>{b}</b></div>)}</div>}
function Timeline(){return <div className="timeline">{["Cadastro da máquina","Upload de placa e fotos","Diagnóstico NR-12 iniciado","APR revisada","GAP registrado","Ação corretiva criada","Checklist pré-operacional","Teste funcional","Revisão de laudo"].map((e,i)=><div key={e}><i/><section><b>{e}</b><p>{demoMachines[i].tag} • {people[i%8]} • Evento fictício</p><small>{String(i+1).padStart(2,"0")}/11/2026 • {8+i}:30 • Revisão {i+1}</small></section></div>)}</div>}

export default App;
